widget.solution:
from collections import deque

def days_to_spread(adj, defaulted):
    day = {f: 0 for f in defaulted}
    queue = deque(defaulted)
    while queue:
        u = queue.popleft()
        for v in adj[u]:
            if v not in day:
                day[v] = day[u] + 1
                queue.append(v)
    if len(day) < len(adj):
        return -1
    return max(day.values()) if day else 0

def batch_rounds(deps):
    jobs = set(deps)
    for pre in deps.values():
        jobs.update(pre)
    after = {j: [] for j in jobs}
    indeg = {j: 0 for j in jobs}
    for job, pre in deps.items():
        for p in pre:
            after[p].append(job)
            indeg[job] += 1
    current = [j for j in jobs if indeg[j] == 0]
    done = rounds = 0
    while current:
        rounds += 1
        done += len(current)
        nxt = []
        for u in current:
            for v in after[u]:
                indeg[v] -= 1
                if indeg[v] == 0:
                    nxt.append(v)
        current = nxt
    return rounds if done == len(jobs) else None

items.prompt:
Your firm's overnight risk run has 40 jobs. Each job lists the jobs it needs first. Last night the scheduler hung and the morning risk report was missing.

Write a short design note for the team covering:

- (a) how you model the run;
- (b) how you compute a valid run order, and what it costs;
- (c) how the same method shows last night's dependencies were impossible;
- (d) how you would report exactly which jobs caused the problem;
- (e) why a DFS that records jobs as it reaches them, or a plain `seen` set, is not enough;
- (f) how the method shows which jobs could run in parallel.
